
import React, { useState, useContext } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { ThemeContext } from '../assets/components/context/ThemeContext';
import DashboardHeader from '../assets/components/DashboardHeader';
import DashboardMenu from '../assets/components/DashboardMenu';
import { Helmet } from 'react-helmet';
import { MessageContext } from '../assets/components/context/MessageContext';
import { UserContext } from '../assets/components/context/ProfileContext';
import minimize from '../assets/images/minimize.svg';
import maximize from '../assets/images/maximize.svg';
import messageclose from '../assets/images/messageclose.svg';
import ReactQuill from 'react-quill';
import 'react-quill/dist/quill.snow.css'; // Import the styles


const ComposeMessage = () => {
  const { isDarkMode } = useContext(ThemeContext);
  const { sendMessage } = useContext(MessageContext);
  const {users, currentUser } = useContext(UserContext);
  const [subject, setSubject] = useState('');
  const [body, setBody] = useState('');
  const [senderImage, setSenderImage] = useState(''); 
  const [recipient, setRecipient] = useState('');

  const handleSubmit = () => {
    const newMessage = {
      id: Date.now(),
      subject,
      body,
      sender: currentUser.email,
      senderImage, // Image will be set by the user
      replies: []
    };

    sendMessage(newMessage, recipient);
    setSubject('');
    setRecipient('');
    setBody('');
    setSenderImage('');
  };


  return (
    <>
    <Helmet>
    <title>Compose Message - Fidar</title>
    </Helmet>
    <div className={`dashboard-main-container ${isDarkMode ? 'dark-mode' : 'light-mode'}`}>
        <div className="dash-col1">
                <DashboardMenu />
            </div>
        <DashboardHeader />
        <div className={`dash-others ${isDarkMode ? 'dark-mode' : 'light-mode'}`}>
            {/*  */}
            <form className="compose-message-container">
              <div className="compose-top-bar">
                  <div className="new-message">New Message</div>
                  <div className="frame-3076">
                    <Link to=""><img className="minimize" src={minimize} /></Link>
                    <Link to=""><img className="open-in-full" src={maximize} /></Link>
                    <Link to="/pages/document"><img className="close" src={messageclose} /></Link>
                  </div>
                </div>
                <div className="recipient-container">
                  <div className="recipient-wrapper">
                    <div className="recipient-to-label">To</div>
                    <input 
                      className="recipient-email" 
                      type='email' 
                      value={recipient} 
                      onChange={(e) => setRecipient(e.target.value)} />
                  </div>
                </div>
                <div className="compose-subject-container">
                  <div className="subject-wrapper">
                    <div className="recipient-subject-label">Subject</div>
                    <input
                          className="recipient-email"
                          type="text"
                          value={subject}
                          onChange={(e) => setSubject(e.target.value)}
                      />
                  </div>
                </div>
                <div className="compose-message-bg1"></div>
                <div className="compose-carbon-copy">Cc Bcc</div>
                <ReactQuill className="word" theme="snow" value={body} onChange={setBody}/>
                <div className="send-compose-container">
                  <button className="send-compose-btn" onClick={handleSubmit}>
                    <div className="send-compose-text">Send</div>
                  </button>
                </div>
                <div className="compose-message-bg1"></div>
                <div className="compose-privacy-container">
                      <div className="message-privacy-count">
                          <div className="message-privacy-bg"></div>
                          <div className="message-privacy-number">5</div>
                      </div>
                      <div className="message-privacy-content">
                          <div className="privacy-note">
                              The privacy and security of your Bank Account details is important to
                              us. If you would prefer that we do not display your account
                          </div>
                      </div>
                  </div>
              </form>
        </div>
    </div>

    </>
  );
};

export default ComposeMessage;
