import React, { createContext, useState, useEffect } from 'react';

// Create the context
export const FileContext = createContext();

const FileProvider = ({ children }) => {
  // Define the state to store different types of files
  const [imageFiles, setImageFiles] = useState([]);
  const [pdfFiles, setPdfFiles] = useState([]);
  const [pptFiles, setPptFiles] = useState([]);

  // Load from localStorage when the app starts
  useEffect(() => {
    const savedImageFiles = JSON.parse(localStorage.getItem('imageFiles')) || [];
    const savedPdfFiles = JSON.parse(localStorage.getItem('pdfFiles')) || [];
    const savedPptFiles = JSON.parse(localStorage.getItem('pptFiles')) || [];
    
    setImageFiles(savedImageFiles);
    setPdfFiles(savedPdfFiles);
    setPptFiles(savedPptFiles);
  }, []);

  // Save files to localStorage whenever they change
  useEffect(() => {
    localStorage.setItem('imageFiles', JSON.stringify(imageFiles));
  }, [imageFiles]);

  useEffect(() => {
    localStorage.setItem('pdfFiles', JSON.stringify(pdfFiles));
  }, [pdfFiles]);

  useEffect(() => {
    localStorage.setItem('pptFiles', JSON.stringify(pptFiles));
  }, [pptFiles]);

  // Function to add a new file
  const addFile = (file, fileType) => {
    switch (fileType) {
      case 'image':
        setImageFiles([...imageFiles, file]);
        break;
      case 'pdf':
        setPdfFiles([...pdfFiles, file]);
        break;
      case 'ppt':
        setPptFiles([...pptFiles, file]);
        break;
      default:
        break;
    }
  };

  return (
    <FileContext.Provider value={{ imageFiles, pdfFiles, pptFiles, addFile }}>
      {children}
    </FileContext.Provider>
  );
};

export default FileProvider;
