import React, {useState, useContext} from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import DashboardHeader from '../assets/components/DashboardHeader';
import DashboardMenu from '../assets/components/DashboardMenu';
import { Helmet } from 'react-helmet';
import { ThemeContext } from '../assets/components/context/ThemeContext';
import { MessageContext } from '../assets/components/context/MessageContext';
import { UserContext } from '../assets/components/context/ProfileContext';
import '../assets/css/MessagePreview.css';
import deletemessage from '../assets/images/deletemessage.svg';
import undo from '../assets/images/undo.svg';
import markasunread from '../assets/images/markasunread.svg';
import drivemove from '../assets/images/drivemove.svg';
import messagestar from '../assets/images/messagestar.svg';
import addalert from '../assets/images/addalert.svg';
import arrowbackmessage from '../assets/images/arrowbackmessage.svg';
import arrowforwardmessage from '../assets/images/arrowforwardmessage.svg';
import messageprint from '../assets/images/messageprint.svg';
import messagedownload from '../assets/images/messagedownload.svg';
import reply from '../assets/images/reply.svg';
import forward from '../assets/images/forward.svg';
import { Tooltip } from 'react-tooltip';
import ReactQuill from 'react-quill';
import 'react-quill/dist/quill.snow.css'; // Import the styles
import DOMPurify from 'dompurify';


const MessagePreview = () => {
    const { isDarkMode } = useContext(ThemeContext);
    const { messages, deleteMessage, approveMessage, declineMessage } = useContext(MessageContext);
    const { currentUser } = useContext(UserContext); // Access currentUser from context
    const { id } = useParams(); // Get message id from URL
    const [body, setBody] = useState('');
    const navigate = useNavigate();

    const message = messages.find((msg) => msg.id === parseInt(id));

    if (!message) return <div>Message not found</div>;

    const Preview = ({ content }) => {
        return (
          <div>
            {/* Sanitize HTML content before rendering */}
            <div dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(content) }} />
            
          </div>
        );
      };

      const handleDelete = (id) => {
        const confirmDelete = window.confirm("Are you sure you want to delete this message?");
        if (confirmDelete) {
          deleteMessage(id);
          alert("Message deleted successfully");
          navigate("/pages/document");
        }
      };
    

  return (
    <>
    <Helmet>
        <title>Message Preview - Fidar</title>
    </Helmet>
    <div className={`dashboard-main-container ${isDarkMode ? 'dark-mode' : 'light-mode'}`}>
        <div className="dash-col1">
                <DashboardMenu />
            </div>
        <DashboardHeader />
        {/* Render tooltips */}
        {/* <ReactTooltip place="top" type="dark" effect="solid" /> */}
        <div className={`dash-others ${isDarkMode ? 'dark-mode' : 'light-mode'}`}>
            {/*  */}
            <div className="message-preview-container">
                {/* top row */}
                <div className="message-top-row">
                    <div className="message-top-left">
                        <Link to="/pages/document">
                            <img className="message-arrow-back" alt='arrow back' data-tooltip-id="my-tooltip" data-tooltip-content="Back to Document" src={arrowbackmessage} />
                            <Tooltip id="my-tooltip" place="top" type="dark" effect="solid" />
                        </Link>
                        <div className="top-left-actions-container">
                            <img onClick={() => handleDelete(message.id)} className="top-left-icon" alt='delete' data-tooltip-id="my-tooltip" data-tooltip-content="Delete" src={deletemessage} />
                            <img className="top-left-icon" alt='mark as unread' data-tooltip-id="my-tooltip" data-tooltip-content="Mark as Read" src={markasunread} />
                            <img className="top-left-icon" alt='move' data-tooltip-id="my-tooltip" data-tooltip-content="Move" src={drivemove} />
                            <img className="top-left-icon" alt='star' data-tooltip-id="my-tooltip" data-tooltip-content="Star" src={messagestar} />
                            <img className="top-left-icon" alt='add alert' data-tooltip-id="my-tooltip" data-tooltip-content="Add Alert" src={addalert} />
                        </div>
                    </div>
                    <div className="top-right-section">
                        <div className="top-right-page-number">1 of 12</div>
                        <div className="top-right-arrow-container">
                            <img className="message-arrow-back" alt='Previvious message' data-tooltip-id="my-tooltip" data-tooltip-content="Previous Message" src={arrowbackmessage} />
                            <img className="message-arrow-forward" alt='Next message' data-tooltip-id="my-tooltip" data-tooltip-content="Next Message" src={arrowforwardmessage} />
                        </div>
                    </div>
                </div>
                {/*  */}
                <div className='message-second-row'>
                    <div className="subject-statement-of-account">Subject: {message.subject}</div>
                    <div className="message-download-action">
                        <img className="message-download" alt='download' data-tooltip-id="my-tooltip" data-tooltip-content="Download" src={messagedownload} />
                        <img className="message-print" alt='print' data-tooltip-id="my-tooltip" data-tooltip-content="Print" src={messageprint} />
                    </div>
                    <div className="message-date-container">
                        {/* <img className="attachment" src="attachment0.svg" /> */}
                        <div className="message-date">{message.date}</div>
                    </div>
                    <div className="message-user-details">
                        <img className="message-user-image" data-tooltip-id="my-tooltip" data-tooltip-content={currentUser.firstName} src={currentUser.profileImage} />
                        <div className="message-user-id-container">
                            <div className="msg-user-id" data-tooltip-id="my-tooltip" data-tooltip-content={message.id}>{message.id}</div>
                            <div className="msg-user-email" data-tooltip-id="my-tooltip" data-tooltip-content={currentUser.email}>{currentUser.email}</div>
                        </div>
                    </div>
                </div>
                <div className="message-preview-bg1"></div>
                {/* 
                {/* Replybody */}
                <div className='message-reply-view'>
                    <h3 className='message-reply-title'>Replies:</h3>
                    {message.replies.map((reply, index) => (
                        <p key={index} className='message-reply'>
                            <span className='reply-info'>{currentUser.firstName}:</span> 
                            <span className='reply-view-content'>{reply.content}</span> 
                            <span className='reply-view-date'>{reply.date}</span>
                        </p>
                    ))}
                </div>
                {/* Message Body */}
                <div class="word">
                    <Preview content={message.body} />
                </div>
                {/*  */}
                <div className="approval-request-container">
                    {message.status === 'Pending' && ( 
                        <>
                        <div className="approve-container" onClick={() => approveMessage(message.id)}>
                            <div className="approve-box">
                                <div className="approved">Approve</div>
                            </div>
                        </div>
                        <div className="approve-container" onClick={() => declineMessage(message.id)}>
                            <div className="decline-box">
                                <div className="declined">Decline</div>
                            </div>
                        </div>
                        </>
                    )}                 
                </div>
                <div className="message-preview-bg2"></div>
                {/*  */}
                <div className="message-privacy-container">
                    <div className="message-privacy-count">
                        <div className="message-privacy-bg"></div>
                        <div className="message-privacy-number">5</div>
                    </div>
                    <div className="message-privacy-content">
                        <div className="privacy-note">
                            The privacy and security of your Bank Account details is important to
                            us. If you would prefer that we do not display your account
                        </div>
                    </div>
                </div>
                {/*  */}
                <div className="message-bottom-container">
                    {/* <div className="message-reply-container"> */}
                    <Link to={`/pages/replymessage/${message.id}`} className="message-reply-container">
                        <img className="message-reply-icon" alt='reply' src={reply} />
                        <div className="message-reply-text">Reply</div>
                    </Link>
                    <div className="message-forward-container">
                        <img className="message-forward-icon" alt='forward' src={forward} />
                        <div className="message-forward-text">Forward</div>
                    </div>
                </div>
            </div>
            {/*  */}
        </div>
    </div>
    </>
  );
};

export default MessagePreview;

