import React, { useContext } from 'react';
import { ThemeContext } from '../../components/context/ThemeContext';
import '../../css/ThemeSwitcher.css';

function ThemeSwitcher() {
  const { isDarkMode, toggleTheme } = useContext(ThemeContext); // Access global theme

  return (
    <div className={`app-container ${isDarkMode ? 'dark-mode' : 'light-mode'}`}>
      <div className="mode-switch" onClick={toggleTheme}>
        <div className="theme-bar">
          <div className={`theme-slider-bar ${isDarkMode ? 'slider-dark' : 'slider-light'}`}></div>
        </div>
        <span className="theme-bar-label">{isDarkMode ? "Dark Mode" : "Light Mode"}</span>
      </div>

      <div className="theme-content">
        <h1>{isDarkMode ? "Dark Mode is ON" : "Light Mode is ON"}</h1>
      </div>
    </div>
  );
}

export default ThemeSwitcher;
