import React from "react";
import '../css/Overview.css';
import jpj from '../images/jpj.svg';
import png from '../images/png.svg';
import cut from '../images/cut.svg';
import compress from '../images/compress.svg';
import merge from '../images/merge.svg';
import powerpoint from '../images/powerpoint.svg';
import { Link } from "react-router-dom";

function Overview() {
    return (
        <>
        <div className="convert-files-heading">Convert Files</div>
        <div className="convert-overview-container">
            <Link to="/pages/jpgtopdf" className="convert-box-2">
                <div className="con-box1-border"></div>
                <div className="box-1">
                    <div className="box-1-top">
                        <div className="box-1-circle"></div>
                        <img className="box-1-image" src={jpj} />
                    </div>
                    <div className="box-1-text-box">
                        <div className="convert-title">JPG TO PDF</div>
                        <div className="convert-sub-title">
                        Convert a JPG
                        <br />
                        to PDF
                        </div>
                    </div>
                </div>
            </Link>
            <Link to="/pages/pngtopdf" className="convert-box-2">
                <div className="con-box-2-border"></div>
                <div className="box-1">
                    <div className="box-1-top">
                        <div className="box-1-circle"></div>
                        <img className="box-1-image" src={png} />
                    </div>
                    <div className="box-1-text-box">
                        <div className="convert-title">PNG to PDF</div>
                        <div className="convert-sub-title">
                        Convert a PNG
                        <br />
                        to PDF
                        </div>
                    </div>
                </div>
            </Link>
            <Link to="/pages/splittopdf" className="convert-box-2">
                <div className="con-box-2-border"></div>
                <div className="box-1">
                    <div className="box-1-top">
                        <div className="box-1-circle"></div>
                        <img className="box-1-image" src={cut} />
                    </div>
                    <div className="box-1-text-box">
                        <div className="convert-title">Split to PDF</div>
                        <div className="convert-sub-title">
                        Split into one or <br /> multple PDF
                        </div>
                    </div>
                </div>
            </Link>
        </div>
        {/* Row 2 */}
        <div className="convert-overview-container">
            <Link to="/pages/powerpointtopdf" className="convert-box-2">
                <div className="con-box1-border"></div>
                <div className="box-1">
                    <div className="box-1-top">
                        <div className="box-1-circle"></div>
                        <img className="box-1-image" src={powerpoint} />
                    </div>
                    <div className="box-1-text-box">
                        <div className="convert-title">Power Point...</div>
                        <div className="convert-sub-title">
                        Convert power point <br /> to PDF
                        </div>
                    </div>
                </div>
            </Link>
            <Link to="/pages/mergepdf" className="convert-box-2">
                <div className="con-box-2-border"></div>
                <div className="box-1">
                    <div className="box-1-top">
                        <div className="box-1-circle"></div>
                        <img className="box-1-image" src={merge} />
                    </div>
                    <div style={{textDecoration: 'none'}} className="box-1-text-box">
                        <div className="convert-title">Merge PDF</div>
                        <div className="convert-sub-title">
                        Merge files into a <br /> single file
                        </div>
                    </div>
                </div>
            </Link>
            <Link to="/pages/compresspdf" className="convert-box-2">
                <div className="con-box-2-border"></div>
                <div className="box-1">
                    <div className="box-1-top">
                        <div className="box-1-circle"></div>
                        <img className="box-1-image" src={merge} />
                    </div>
                    <div style={{textDecoration: 'none'}} className="box-1-text-box">
                        <div className="convert-title">Compress PDF</div>
                        <div className="convert-sub-title">
                        Convert a JPG
                        <br />
                        to PDF
                        </div>
                    </div>
                </div>
            </Link>
        </div>

        </>
    )
}

export default Overview;