import React from "react";
import { Helmet } from "react-helmet";
import '../assets/css/Login.css';
import welcomeicon from '../assets/images/welcomeicon.svg';
import google from '../assets/images/google.svg';
import facebook from '../assets/images/facebook.svg';
import { Link } from "react-router-dom";

function Login() {
    return (
        <>
        <Helmet>
            <title>Reset Password - Fidar</title>
        </Helmet>
        <div className="reset-password-page">
            <div className="sign-in-container">
                <div className="sign-in-contents">
                    <Link to="/"><img className="reset-back-to-home" src={welcomeicon} /></Link>
                    <form className="frame-8">
                        <div className="forgotten-password-title">Forgotten Password?</div>
                        <div className="get-reset-container">
                            <div className="get-reset-wrapper">
                                <div className="get-reset-link-with-your-email">Get reset link with your email</div>
                            </div>
                        </div>
                        <div className="reset-input-box">
                            <div className="reset-input-container">
                                    <input type="email" className="email-input" placeholder="Type in your email" required/>
                            </div>
                        </div>
                        <button className="reset-btn-box">
                            <div className="button4">Get Link</div>
                        </button>
                    </form>
                    <Link to="/pages/login" className="remember-your-password-log-in">Remember your password? <span style={{color: "#35b2f6", marginLeft: "5px"}}>Log In</span></Link>
                </div>
            </div>
        </div>

        </>
    )
}

export default Login;