import React, { useState, useContext } from 'react';
import { Helmet } from 'react-helmet';
import { Link } from 'react-router-dom';
import DashboardMenu from '../assets/components/DashboardMenu';
import DashboardHeader from '../assets/components/DashboardHeader';
import { ThemeContext } from '../assets/components/context/ThemeContext';
import recentavatar from '../assets/images/recentavatar.svg';
import recentstar from '../assets/images/recentstar.svg';
import more from '../assets/images/more.svg';
import '../assets/css/Inbox.css';
import '../assets/css/Test.css';
import { MessageContext } from '../assets/components/context/MessageContext';
import { UserContext } from '../assets/components/context/ProfileContext';
import pencil from '../assets/images/pencil.svg';
import addphoto from '../assets/images/addphoto.svg';
import '../assets/css/ComposeMessage.css';
import DOMPurify from 'dompurify';
import 'react-quill/dist/quill.snow.css'; // Import the styles



function Document() {
  const { isDarkMode } = useContext(ThemeContext);
  const { messages, approveMessage, declineMessage } = useContext(MessageContext);
  const {currentUser } = useContext(UserContext); // Access currentUser from context

  const Preview = ({ content }) => {
    const limitedContent = content.split(' ').slice(0, 10).join(' ') + (content.split(' ').length > 4 ? '...' : '');
    return (
      <div>
        <div className='preview-word' dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(limitedContent) }} />
      </div>
    );
  };

  // Function to determine the style based on the status
  const getStatusStyle = (status) => {
    switch (status) {
      case 'Approved':
        return { color: 'green' };
      case 'Declined':
        return { color: 'red' };
      case 'Pending':
        return { color: 'blue' };
      default:
        return {};
    }
  };

  return (
    <>
      <Helmet>
        <title>Document - Fidar</title>
      </Helmet>
      <div className={`dashboard-main-container ${isDarkMode ? 'dark-mode' : 'light-mode'}`}>
      <div className="dash-col1">
        <DashboardMenu />
      </div>
        <DashboardHeader />
        <div className={`dash-others ${isDarkMode ? 'dark-mode' : 'light-mode'}`}>
          {/* Mobile Top Bar */}
          <div className="mobile-top-bar">
            <div className="mobile-inbox-top-left">
              <Link to="/pages/dashboard">
                <i className="my-back-arrow fa-solid fa-chevron-left"></i>
              </Link>
              <Link to="/pages/dashboard" className="mobile-inbox-back-btn">Back</Link>
              <div className="mobile-inbox-title">Chat</div>
            </div>
          </div>

          {/* Inbox Top Bar */}
          <div className="top-inbox-bar">
            <div className="inbox-top-left">
              <div className="inbox-check-box">
                <input type="checkbox" className="inbox-check" />
              </div>
              <div className="inbox-username">Username</div>
            </div>
            <div className="inbox-description">Description</div>
            <img className="inbox-more" src={more} alt="More options" />
          </div>
          <div class="compose-wrapper">
            <Link class="edit" to="/pages/composemessage"><img class="compose-btn" src={pencil} /></Link>
            <Link class="edit" to="/pages/composemessage"><img class="add-a-photo" src={addphoto} /></Link>
          </div>

          {/* Message Rows */}
          <div className={`frame-16-unique ${isDarkMode ? 'dark-mode' : 'light-mode'}`}>
              {/* Row */}
              {messages.length === 0 ? (
              <p>No messages available.</p>
              ) : (
              <ul style={{listStyle: 'none', width: '100%', marginLeft: '-40px'}}>
                {messages.map((message) => (
                <li key={message.id}>
                    <Link to={`/pages/message/${message.id}`} style={{textDecoration:"none"}}>
                        <div className="component-3-unique">
                            <div className="frame-61-unique">
                                <div className="check-box-unique">
                                    <input type="checkbox" className="rectangle-3036-unique"/>
                                </div>
                                <img className="star-4-unique" src={recentstar} />
                                <div className="frame-60-unique">
                                    <img className="avatar-8-unique" src={currentUser.profileImage} />
                                    <div className="group-1892-unique">
                                        <div className="fd-2481-41-b-unique">{message.id}</div>
                                        <div className="tom-hanks-unique">{currentUser.firstName} {currentUser.lastName}</div>
                                    </div>
                                </div>
                            </div>
                            <div className="frame-59-unique" />
                                <div className="statement-of-account-unique">
                                    <span>
                                        <span className="statement-of-account-span-unique">
                                        {message.subject}
                                        <br />
                                        </span>
                                        <span className="statement-of-account-span2-unique">
                                        <Preview content={message.body} />
                                        </span>
                                    </span>
                                </div>
                                
                            <div className="message-time-stamp">
                              <span className='document-status'>
                                <span className='document-status-text'>Status:</span>
                                <b style={getStatusStyle(message.status)}>{message.status}</b>
                              </span> 
                              <span className='message-date'>{message.date}</span>
                            </div>
                        </div>
                </Link>
              </li>
                ))}
                </ul>
                )}
            </div>
        </div>

        
      </div>
    </>
  );
}

export default Document;


