import React, { useState, useRef, useEffect } from 'react';
import '../css/HomeHeader.css';
import '../css/BgPattern.css';
import fidarlogo from '../images/fidarlogo.svg';
import { Link } from "react-router-dom";
import Hero from './Hero';

function HomeHeader(){
    const [isMenuOpen, setIsMenuOpen] = useState(false);
    const menuRef = useRef(null);

    const toggleMenu = () => {
        setIsMenuOpen(!isMenuOpen);
    };

    // Close menu when clicking outside
    useEffect(() => {
        const handleClickOutside = (event) => {
        if (menuRef.current && !menuRef.current.contains(event.target)) {
            setIsMenuOpen(false); // Close the menu if clicked outside
        }
        };
        
        document.addEventListener('mousedown', handleClickOutside);
        
        return () => {
        document.removeEventListener('mousedown', handleClickOutside);
        };
    }, [menuRef]);


    return (
        <>
            <div className="header-wrapper">
                <Link to="/" className='logo-wrapper'>
                    <img src={fidarlogo} alt="logo" />
                    <div>Fidar</div>
                </Link>
                <div class="large-nav-wrapper">
                    <div class="link-container">
                        <Link to="/" class="nav-link nav-link-active">Home</Link>
                        <Link to="/pages/freqask" class="nav-link">FAQ</Link>
                        <Link to="/pages/blog" class="nav-link">Blog</Link>
                        <Link to="/pages/about" class="nav-link">About Us</Link>
                    </div>
                    <div class="call-to-action-container">
                        <Link to="/pages/login" class="cta-login">Login</Link>
                        <Link to="/pages/signup" class="cta-signup">
                            <div class="cta-signup-text">Sign Up</div>
                        </Link>
                    </div>
                </div>

                {/* Mobileheader section */}
                <div className="mobile-nav-wrapper">
                    <div ref={menuRef} className={`mobile-menu ${isMenuOpen ? 'open' : ''}`}>
                       <button className="close-menu-btn" onClick={toggleMenu}>X</button>
                        <div className="link-container">
                            <Link to="/" className="nav-link nav-link-active">Home</Link>
                            <Link to="/pages/freqask" className="nav-link">FAQ</Link>
                            <Link to="/pages/blog" className="nav-link">Blog</Link>
                            <Link to="/pages/about" className="nav-link">About Us</Link>
                            <Link to="/pages/login" className="cta-login">Login</Link>
                            <Link to="/pages/signup" className="cta-signup">
                                <div className="cta-signup-text">Sign Up</div>
                            </Link>
                        </div>
                    </div>
                    {/* Menu Toggle Button */}
                    <div className="menu-toggle" onClick={toggleMenu}>
                        <div className={`burger ${isMenuOpen ? 'open' : ''}`}></div>
                        <div className={`burger ${isMenuOpen ? 'open' : ''}`}></div>
                        <div className={`burger ${isMenuOpen ? 'open' : ''}`}></div>
                    </div>
                </div>
            </div>
        </>
    )
}

export default HomeHeader;