import React from "react";
import aboutimage from '../assets/images/aboutimage.svg';
import { Helmet } from "react-helmet";
import HomeHeader from "../assets/components/HomeHeader";
import Footer from "../assets/components/Footer";
import '../assets/css/Blog.css';


function Blog() {
    return (
        <>
        <Helmet>
            <title>Blog - Fidar</title>
        </Helmet>
        <HomeHeader />
        <div className="blog-container">
            <div className="about-top">
                <div className="about-fidar">Blog</div>
                <img className="about-top-image" src={aboutimage} />
            </div>
        </div>
        <Footer />
        </>
    )
}

export default Blog;