import React, { useState } from "react";
import '../css/ChoosePlanStyle.css';
import bulletpoint from '../images/bulletpoint.svg';
import { Link } from "react-router-dom";
import PricingPlan from "./Test";


function ChoosePlan() {
  const [billingCycle, setBillingCycle] = useState('monthly'); // Default to monthly billing

  const handleBillingToggle = (cycle) => {
    setBillingCycle(cycle);
  };
  
    return (
        <>
        <div className="choose-plan-wrapper">
          <div class="chooseplan-bg-pattern-2"></div>
          <div className="choose-plan-top-section">
            <div className="choose-plan-title">
              Choose Plan
              <br />
              That’s Right For You
            </div>
            <div className="choose-plan-sub-title">
              Choose plan that works best for you, feel free to contact us
            </div>
            <div className="choose-plan-switch-container">
              <div className="choose-monthly-container">
                <div className={`bill-monthly ${billingCycle === 'monthly' ? 'billactive' : ''}`} onClick={() => handleBillingToggle('monthly')}>
                  <p>Bill Monthly</p>
                </div>
              </div>
              <div className="choose-yearly-container">
                <div className={`bil-yearly ${billingCycle === 'yearly' ? 'billactive' : ''}`}  onClick={() => handleBillingToggle('yearly')}>
                  <p>Bill Yearly</p>
              </div>
              </div>
            </div>
          </div>
          <div className="choose-plan-bottom-container">
            {/* Plan 1 */}
            <div className="plan-container">
              <div className="plan-top">
              <div className="plan-title">Free</div>
              <div className="plan-description">
              Have a go and test your superpowers
              </div>
              <div className="plan-amount-container">
                  <div className="plan-amount-symbol">$</div>
                  <div className="plan-amount">0</div>
              </div>
              </div>
              <div className="plan-box">
              <div className="plan-features-list-container">
                  <div className="plan-features-wrapper">
                  <img className="plan-feature-icon" src={bulletpoint} />
                  <div className="plan-feature-icon-text">2 Users</div>
                  </div>
                  <div className="plan-features-wrapper">
                  <img className="plan-feature-icon" src={bulletpoint} />
                  <div className="plan-feature-icon-text">2 Files</div>
                  </div>
                  <div className="plan-features-wrapper">
                  <img className="plan-feature-icon" src={bulletpoint} />
                  <div className="plan-feature-icon-text">
                  Public Share &amp; Comments
                  </div>
                  </div>
                  <div className="plan-features-wrapper">
                  <img className="plan-feature-icon" src={bulletpoint} />
                  <div className="plan-feature-icon-text">Chat Support</div>
                  </div>
                  <div className="plan-features-wrapper">
                  <img className="plan-feature-icon" src={bulletpoint} />
                  <div className="plan-feature-icon-text">New income apps</div>
                  </div>
              </div>
              <div className="plan-btn-wrapper">
                  <Link to="/pages/signup" className="plan-btn-bg" />
                  <Link to="/pages/signup" className="plan-signup-for-free">Goto Business</Link>
              </div>
              </div>
            </div>
            {/* Plan 2 */}
            <div className="pro-plan-container">
              <div className="plan-top">
                <div className="pro-plan-title">Pro</div>
                <div className="pro-plan-description">
                Unveil new superpowers and join the Design Leaque
                </div>
                <div className="plan-amount-container">
                    <div className="pro-plan-amount-symbol">$</div>
                    <div className="pro-plan-amount">{billingCycle === 'monthly' ? '8' : '80'}{billingCycle === 'yearly'}</div>
                </div>
              </div>
              <div className="plan-box">
                <div className="plan-features-list-container">
                  <div className="plan-features-wrapper">
                    <img className="plan-feature-icon" src={bulletpoint} />
                    <div className="plan-feature-icon-text">All apps</div>
                  </div>
                  <div className="plan-features-wrapper">
                    <img className="plan-feature-icon" src={bulletpoint} />
                    <div className="plan-feature-icon-text">4 Users</div>
                  </div>
                  <div className="plan-features-wrapper">
                    <img className="plan-feature-icon" src={bulletpoint} />
                    <div className="plan-feature-icon-text">
                    Unlimited editable exports
                    </div>
                  </div>
                  <div className="plan-features-wrapper">
                    <img className="plan-feature-icon" src={bulletpoint} />
                    <div className="plan-feature-icon-text">Folders and collaboration</div>
                  </div>
                  <div className="plan-features-wrapper">
                    <img className="plan-feature-icon" src={bulletpoint} />
                    <div className="plan-feature-icon-text">All incoming apps</div>
                  </div>
              </div>
              <div className="plan-btn-wrapper">
                  <Link to="/pages/signup" className="plan-btn-bg" />
                  <Link to="/pages/signup" className="plan-signup-for-free">Goto Business</Link>
              </div>
              </div>
              <div className="pro-plan-bg" />
            </div>
            {/* plan 3 */}
            <div className="plan-container">
              <div className="plan-top">
                <div className="plan-title">Business</div>
                <div className="plan-description">
                Unveil new superpowers and join the Design Leaque
                </div>
                <div className="plan-amount-container">
                    <div className="plan-amount-symbol">$</div>
                    <div className="plan-amount">{billingCycle === 'monthly' ? '50' : '160'}{billingCycle === 'yearly'}</div>
                </div>
              </div>
              <div className="plan-box">
                <div className="plan-features-list-container">
                  <div className="plan-features-wrapper">
                    <img className="plan-feature-icon" src={bulletpoint} />
                    <div className="plan-feature-icon-text">All the features of pro plan</div>
                  </div>
                  <div className="plan-features-wrapper">
                    <img className="plan-feature-icon" src={bulletpoint} />
                    <div className="plan-feature-icon-text">Account success Manager</div>
                  </div>
                  <div className="plan-features-wrapper">
                    <img className="plan-feature-icon" src={bulletpoint} />
                    <div className="plan-feature-icon-text">
                    Single Sign-On (SSO)
                    </div>
                  </div>
                  <div className="plan-features-wrapper">
                    <img className="plan-feature-icon" src={bulletpoint} />
                    <div className="plan-feature-icon-text">Co-conception pogram</div>
                  </div>
                  <div className="plan-features-wrapper">
                    <img className="plan-feature-icon" src={bulletpoint} />
                    <div className="plan-feature-icon-text">Collaboration-Soon</div>
                  </div>
              </div>
              <div className="plan-btn-wrapper">
                  <Link to="/pages/signup" className="plan-btn-bg" />
                  <Link to="/pages/signup" className="plan-signup-for-free">Goto Business</Link>
              </div>
              </div>
            </div>
          </div>
        </div>

        </>
    )
}

export default ChoosePlan;