import React, { useState, useContext } from "react";
import { Helmet } from "react-helmet";
import { useNavigate } from "react-router-dom";
import { ThemeContext } from '../assets/components/context/ThemeContext';
import DashboardMenu from '../assets/components/DashboardMenu';
import DashboardHeader from "../assets/components/DashboardHeader";
import { UserContext } from "../assets/components/context/ProfileContext";


function AdminDashboard() {
    const { isDarkMode } = useContext(ThemeContext); // Access theme
    const { users, addUser, deleteUser, disableUser, enableUser, changeUserRole } = useContext(UserContext); // Import addUser and other functions
    const [newUser, setNewUser] = useState({ firstName: '', lastName: '', email: '', password: '', role: 'user' }); // Form state
    const [selectedRole, setSelectedRole] = useState('user');  // Default role to 'user'
    const [error, setError] = useState(''); // Error handling

    // const navigate = useNavigate(); // Use to redirect after adding user

    // Handle form input
    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setNewUser(prevState => ({ ...prevState, [name]: value }));
    };

    const handleAddUser = (e) => {
        e.preventDefault();
    
        // Validate if admin is adding a user
        if (!newUser.email || !newUser.password || !newUser.firstName || !newUser.lastName) {
            setError('Please fill in all fields.');
            return;
        }
    
        // Check if email already exists
        const existingUser = users.find(user => user.email === newUser.email);
        if (existingUser) {
            setError('A user with this email already exists.');
            return;
        }
    
        // Add the new user
        addUser({ ...newUser, role: selectedRole });  // Add the user with selected role
        setError('');
    };

    return (
        <>
        <Helmet>
            <title>Add New Users - Fidar</title>
        </Helmet>
        <div className={`dashboard-main-container ${isDarkMode ? 'dark-mode' : 'light-mode'}`}>
            <div className="dash-col1">
                <DashboardMenu />
            </div>
            <DashboardHeader />
            <div className="dash-others">
                <div className="add-user-wrapper">
                    <h2 className="user-title">Add New User</h2>
                    <form onSubmit={handleAddUser} className="add-user-form">
                        {error && <p style={{ color: 'red' }}>{error}</p>}
                        <div className="add-input-box">
                            <label>First Name:</label>
                            <input
                                className="add-user-input"
                                type="text"
                                name="firstName"
                                value={newUser.firstName}
                                onChange={handleInputChange}
                                required
                            />
                        </div>
                        <div className="add-input-box">
                            <label>Last Name:</label>
                            <input
                                className="add-user-input"
                                type="text"
                                name="lastName"
                                value={newUser.lastName}
                                onChange={handleInputChange}
                                required
                            />
                        </div>
                        <div className="add-input-box">
                            <label>Email:</label>
                            <input
                                className="add-user-input"
                                type="email"
                                name="email"
                                value={newUser.email}
                                onChange={handleInputChange}
                                required
                            />
                        </div>
                        <div className="add-input-box">
                            <label>Password:</label>
                            <input
                                className="add-user-input"
                                type="password"
                                name="password"
                                value={newUser.password}
                                onChange={handleInputChange}
                                required
                            />
                        </div>
                        <div className="add-input-box">
                            <label>Role:</label>
                            <select
                                className="add-user-input"
                                name="role"
                                value={selectedRole}
                                onChange={(e) => setSelectedRole(e.target.value)}  // Set selected role
                            >
                                <option value="user">User</option>
                                <option value="admin">Admin</option>  {/* Allow admin to be set */}
                            </select>
                        </div>
                        <button type="submit">Add User</button>
                    </form>
                </div>

                {/* <div>
                    <h2>All Users</h2>
                    <table className="manage-user-tabel">
                        <thead>
                            <tr>
                                <th>Name</th>
                                <th>Email</th>
                                <th>Role</th>
                                <th>Status</th>
                                <th>Actions</th>
                            </tr>
                        </thead>
                        <tbody>
                            {users.map(user => (
                                <tr key={user.email}>
                                    <td>{user.firstName} {user.lastName}</td>
                                    <td>{user.email}</td>
                                    <td>
                                        <select
                                            value={user.role}
                                            onChange={(e) => changeUserRole(user.email, e.target.value)}
                                        >
                                            <option value="user">User</option>
                                            <option value="admin">Admin</option>
                                        </select>
                                    </td>
                                    <td>{user.disabled ? 'Disabled' : 'Active'}</td>
                                    <td>
                                        {user.disabled ? (
                                            <button onClick={() => enableUser(user.email)}>Enable</button>
                                        ) : (
                                            <button onClick={() => disableUser(user.email)}>Disable</button>
                                        )}
                                        <button onClick={() => deleteUser(user.email)}>Delete</button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div> */}
            </div>
        </div>
        </>
    );
}

export default AdminDashboard;
