import React from "react";
import { Helmet } from "react-helmet";
import DashboardMenu from '../assets/components/DashboardMenu';
import DashboardHeader from "../assets/components/DashboardHeader";
import SplitToPdfComponent from "../assets/components/SplitToPdfComponent";
import { useContext } from 'react';
import { ThemeContext } from '../assets/components/context/ThemeContext';

function SplitToPdf() {
    const { isDarkMode } = useContext(ThemeContext); // Access theme

    return (
        <>
        <Helmet>
            <title>Split To PDF - Fidar</title>
        </Helmet>
        <div className={`dashboard-main-container ${isDarkMode ? 'dark-mode' : 'light-mode'}`}>
            <div className="dash-col1">
                <DashboardMenu />
            </div>
            <DashboardHeader />
            <div className="dash-others">
                <SplitToPdfComponent />
            </div>
        </div>
        </>
    )
}

export default SplitToPdf;