import React from "react";
import '../css/WaitingListStyle.css';
import '../css/BgPattern.css';

function WaitingList() {
    return (
        <>
        <div className="waiting-list-wrapper">
          <div className="waiting-pattern-3"></div>
          <div className="waiting-left-side">
            <div className="join-waiting-list">Join waiting List</div>
            <div className="be-the-first-to-know-join-our-exclusive-launch-notification-list-get-ready-for-the-launch-of-fidar-the-ultimate-collaboration-platform">
              Be the First to Know! Join Our Exclusive Launch Notification List
              <br />
              Get ready for the launch of Fidar, the ultimate collaboration platform.
            </div>
          </div>
          <div className="waiting-right-side">
            <form className="waiting-email-wrapper">
              <input className="waiting-email" type="email" placeholder="Enter your email here" required/>
              <button className="waiting-btn-wrapper">
                <div className="rectangle-95" />
                <div className="join-now">Join Now</div>
              </button>
            </form>
          </div>
        </div>
        </>
    )
}

export default WaitingList;