import React from "react";
import globe from '../images/globe.svg';
import '../css/Hero.css';
import herocurve from '../images/herocurve.svg';
import play from '../images/Play.svg';
import { Link } from "react-router-dom";

function Hero() {
    return (
        <>
        <div className="hero-wrapper">
            <div className="bg-pattern-2"></div>
            <div className="bg-pattern-3"></div>
            <div className="hero-text">
                <div className="hero-title">Fidar: Revolutionize your document sharing game.</div>
                <div className="sub-title-container">
                    <img className="hero-curve" src={herocurve} />
                    <div className="sub-title-wrapper">
                        <div className="hero-sub-title">
                        Share, Track, Chat, Convert, Compose - All in One
                        </div>
                        <div className="hero-bottom">
                            <Link to="/pages/signup" className="hero-bottom-1">
                                <div className="hero-bottom-1-text">Try free trial</div>
                            </Link>
                            <Link to="" className="hero-bottom-2">
                                <div className="hero-icon-container">
                                    <img className="hero-play" src={play} />
                                </div>
                                <div className="hero-view-demo">View Demo</div>
                            </Link>
                        </div>
                    </div>
                </div>
            </div>
            <div className="hero-image-container">
                <img className="hero-image" src={globe} />
            </div>
        </div>

        </>
    )
}

export default Hero;