import React from "react";
import '../css/Clients.css';
import block from '../images/block.svg';
import threelines from '../images/threelines.svg';
import animal from '../images/animal.svg';
import jigsaw from '../images/jigsaw.svg';
import renewit from '../images/renewit.svg';

function Clients() {
    return (
        <>
        <div className="client-wrapper">
            <div className="client-section-title">
                Clients that have tested Fidar
            </div>
            <div className="clients-logo-wrapper">
                <img className="block" src={block} />
                <img className="threelines" src={threelines} />
                <img className="animal-img" src={animal} />
                <img className="jigsaw-img" src={jigsaw} />
                <img className="layer-15" src={renewit} />
            </div>
        </div>
        </>
    )
}

export default Clients;