import React from "react";
import '../css/FooterStyle.css';
import { Link } from "react-router-dom";
import footerarrow from '../images/footerarrow.svg';

function Footer() {
    return (
        <>
        <div className="footer-container">
          <div className="footer-bg" />
          <div className="footer-wrapper">
            <div className="footer-col-1">
              <Link to="/" className="fidar">Fidar</Link>
              <div className="get-started-now-try-our-product">
                Get started now try our product
              </div>
              <form className="footer-email-container">
                <input className="footer-email-input" type="email" placeholder="Enter your email here" required/>
                <button className="footer-arrow-btn" type="submit" style={{backgroundColor: "transparent", outline: "none", border: "none"}}>
                  <div className="footer-arrow-container" />
                  <img className="arrow-right-1-1" src={footerarrow} />
                </button>
              </form>
            </div>
            <div className="footer-col-2">
              <div className="footer-link-col-1">
                <Link to="" className="footer-link">Support</Link>
                <Link to="" className="footer-link">Help centre</Link>
                <Link to="/pages/login" className="footer-link">Account information</Link>
                <Link to="" className="footer-link">About</Link>
                <Link to="" className="footer-link">Contact us</Link>
              </div>
              <div className="footer-link-col-2">
                <Link to="" className="footer-link">Help and Solution</Link>
                <Link to="" className="footer-link">Talk to support</Link>
                <Link to="" className="footer-link">Support docs</Link>
                <Link to="" className="footer-link">System status</Link>
                <Link to="" className="footer-link">Covid responde</Link>
              </div>
              <div className="footer-link-col-3">
                <Link to="" className="footer-link">Product</Link>
                <Link to="" className="footer-link">Update</Link>
                <Link to="" className="footer-link">Security</Link>
                <Link to="" className="footer-link">Beta test</Link>
                <Link to="" className="footer-link">Pricing product</Link>
              </div>
            </div>
            <div className="footer-bottom-section">
              <div className="copywrite">
                © 2024 Biccas Inc. Copyright and rights reserved
              </div>
              <div className="terms-condition-container">
                <Link to="" className="terms-and-condtions">Terms and Condtions</Link>
                <Link to="" className="privacy-policy">Privacy Policy</Link>
              </div>
            </div>
          </div>
        </div>

        </>
    )
}

export default Footer;