import React, { useState, useEffect } from "react";
import profileimage from '../../images/profileimage.svg';
import { useContext } from 'react';
import { ThemeContext } from '../context/ThemeContext';
import { UserContext } from "../context/ProfileContext";
import inbox from '../../images/inbox.svg';

function Profile() {
    const { isDarkMode } = useContext(ThemeContext); // Access theme
    const { currentUser, updateCurrentUser } = useContext(UserContext); // Access user from context
    // const [profileImage, setProfileImage] = useState(currentUser.profileImage || '');

    // Local state to handle form inputs
    const [firstName, setFirstName] = useState(currentUser.firstName || '');
    const [lastName, setLastName] = useState(currentUser.lastName || '');
    const [email, setEmail] = useState(currentUser.email || '');
    const [profileImage, setProfileImage] = useState(currentUser.profileImage || '');

    // Handle image upload
    const handleImageUpload = (e) => {
        const file = e.target.files[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => {
                const updatedUser = { ...currentUser, profileImage: reader.result }; // Update user object with image
                updateCurrentUser(updatedUser); // Save to context and localStorage
                setProfileImage(reader.result); // Set local state to display
            };
            reader.readAsDataURL(file);
        }
    };

    // Handle form submission to update user details
    const handleFormSubmit = (e) => {
        e.preventDefault();

        // Update user information in context and localStorage
        const updatedUser = {
            ...currentUser,
            firstName,
            lastName,
            email,
            profileImage
        };

        updateCurrentUser(updatedUser); // Update the user in context
        alert('User details updated successfully!');
    };

    
    return (
        <>
        <div className={`profile-title ${isDarkMode ? 'dark-mode' : 'light-mode'}`}>Avatar</div>
        <div className={`profile-sub-title ${isDarkMode ? 'dark-mode' : 'light-mode'}`}>Update your avatar by clicking the image below. 288x288 px size recommended in PNG or JPG format only.</div>

        <form className={` ${isDarkMode ? 'dark-mode' : 'light-mode'}`} onSubmit={handleFormSubmit}>
            <div className="profile-image">
                <div className="profile-icon-wrapper">
                    <img className="profile-icon" src={inbox} />
                    <input type="file" accept="image/*" onChange={handleImageUpload} />
                </div>
            </div>
            {/* Display the uploaded image dynamically */}
            {profileImage && (
                <div className="profile-picture">
                    <h4>Profile Picture Preview:</h4>
                    {/* If no uploaded image, display the default placeholder image */}
                    <img src={profileImage} alt="Profile" style={{ width: '150px', height: '150px', borderRadius: '50%', border: "2px solid #ccc", padding: "2px" }} />
                </div>
            )}
            
            <button className="remove-image-btn" onClick={() => {
                localStorage.removeItem('profileImage'); // Remove image from localStorage
                setProfileImage(null); // Clear image in the state
            }}>
                Remove Image
            </button>
        
            <input type="text" className="security-input" placeholder="First name" value={firstName} onChange={(e) => setFirstName(e.target.value)} />
            <input type="text" className="security-input" placeholder="Last Name" value={lastName} onChange={(e) => setLastName(e.target.value)}/>
            <input type="text" className="security-input" placeholder="Email Address" value={email} onChange={(e) => setEmail(e.target.value)}/>
            <button type="submit" className="security-btn">
                <div className="save-changes">Save changes</div>
            </button>
        </form>
        </>
    )
}

export default Profile;