import React, { useState, useContext } from "react";
import { Helmet } from "react-helmet";
import { ThemeContext } from '../assets/components/context/ThemeContext';
import DashboardHeader from "../assets/components/DashboardHeader";
import DashboardMenu from "../assets/components/DashboardMenu";
import { UserContext } from "../assets/components/context/ProfileContext";
import '../assets/css/Users.css';

function AdminDashboard() {
    const { isDarkMode } = useContext(ThemeContext); // Access theme
    const { users, deleteUser, disableUser, enableUser, changeUserRole, changeUserPassword } = useContext(UserContext); // Import changeUserRole
    const [selectedUserEmail, setSelectedUserEmail] = useState('');  // State to store selected email

    const grantAdmin = () => {
        if (selectedUserEmail) {
            console.log('Granting admin access to:', selectedUserEmail);  // Debug line
            changeUserRole(selectedUserEmail, 'admin');  // Change selected user's role to admin
            alert(`${selectedUserEmail} has been granted admin access`);
        } else {
            alert('Please select a user');
        }
    };
    

    const [selectedRole, setSelectedRole] = useState('');  // Track the role to be set
    const [selectedUser, setSelectedUser] = useState(null);  // Track which user is selected for password change
    const [newPassword, setNewPassword] = useState('');      // Track the new password input
    const [error, setError] = useState('');

    const handleRoleChange = (email, newRole) => {
        changeUserRole(email, newRole);  // Update the user's role using changeUserRole from context
    };

    // Function to handle password change
    const handlePasswordChange = () => {
        if (!newPassword) {
            setError("Password cannot be empty.");
            return;
        }

        changeUserPassword(selectedUser.email, newPassword);  // Call the function to change the password
        setSelectedUser(null);  // Clear selected user after password change
        setNewPassword('');     // Reset the new password input
        setError('');           // Clear error message
    };

    // Calculate the number of admin users
    const totalAdmins = users.filter(user => user.role === 'admin').length;

    // Calculate the number of regular users
    const totalRegularUsers = users.filter(user => user.role === 'user').length;


    return (
        <>
        <Helmet>
            <title>All Users - Fidar</title>
        </Helmet>
        <div className={`dashboard-main-container ${isDarkMode ? 'dark-mode' : 'light-mode'}`}>
            <div className="dash-col1">
                <DashboardMenu />
            </div>
            <DashboardHeader />
            <div className="dash-others">
                <div className="user-wrapper">
                    <h2 className="user-title">Manage Users</h2>
                    <div className="users-top-row">
                        <p className="manage-user-label">Total Registered Users: {users.length}</p>
                        <p className="manage-user-label">Total Admins: {totalAdmins}</p>
                        <p className="manage-user-label">Total Regular Users: {totalRegularUsers}</p>
                    </div>
                    <table className="manage-user-tabel">
                        <thead>
                            <tr>
                                <th>Name</th>
                                <th>Email</th>
                                <th>Role</th>
                                <th>Status</th>
                                <th>Actions</th>
                                <th>Reset Password</th>
                            </tr>
                        </thead>
                        <tbody>
                            {users.map(user => (
                                <tr key={user.email}>
                                    <td>{user.firstName} {user.lastName}</td>
                                    <td>{user.email}</td>
                                    <td>
                                        {/* Dropdown to select role */}
                                        <select
                                            value={user.role}
                                            onChange={(e) => handleRoleChange(user.email, e.target.value)}
                                        >
                                            <option value="user">User</option>
                                            <option value="admin">Admin</option>
                                        </select>
                                    </td>
                                    <td>{user.disabled ? 'Disabled' : 'Active'}</td>
                                    <td>
                                        {user.disabled ? (
                                            <button onClick={() => enableUser(user.email)}>Enable</button>
                                        ) : (
                                            <button onClick={() => disableUser(user.email)}>Disable</button>
                                        )}
                                        <button onClick={() => deleteUser(user.email)}>Delete</button>
                                    </td>
                                    <td>
                                        {/* Button to change password */}
                                        <button onClick={() => setSelectedUser(user)}>
                                            Change Password
                                        </button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                    <h3>Select a User to Grant Admin Access</h3>

                    <select 
                        value={selectedUserEmail} 
                        onChange={(e) => setSelectedUserEmail(e.target.value)}
                    >
                        <option value="">-- Select User --</option>
                        {users.map((user) => (
                            <option key={user.email} value={user.email}>
                                {user.firstName} {user.lastName} ({user.email})
                            </option>
                        ))}
                    </select>

                    <button onClick={grantAdmin}>Grant Admin Access</button>

                    {/* Show password change form if a user is selected */}
                    {selectedUser && (
                        <div>
                            <h3>Change Password for {selectedUser.firstName} {selectedUser.lastName}</h3>
                            <label>
                                New Password:
                                <input 
                                    type="password" 
                                    value={newPassword}
                                    onChange={(e) => setNewPassword(e.target.value)} 
                                />
                            </label>
                            {error && <p style={{ color: 'red' }}>{error}</p>}
                            <button onClick={handlePasswordChange}>Update Password</button>
                            <button onClick={() => setSelectedUser(null)}>Cancel</button>
                        </div>
                    )}
                </div>
            </div>
        </div>
        </>
    );
}

export default AdminDashboard;
