import React, {useContext, useState} from "react";
import { FileContext } from "./context/FileContext";
import '../css/MergePdfComponent.css';
import arrowback from '../images/arrowback.svg';
import { Link, useNavigate } from "react-router-dom";
import { useDropzone } from 'react-dropzone';
import docu2 from '../images/docu2.svg';
import { ThemeContext } from "./context/ThemeContext";

function CompressPdfComponent() {
    const { isDarkMode } = useContext(ThemeContext);
    const [filePath, setFilePath] = useState('');
    const [file, setFile] = useState(null);  // Store the file object
    const { addFile } = useContext(FileContext);
    const navigate = useNavigate();  // Use navigate to redirect
    
    const { getRootProps, getInputProps } = useDropzone({
        accept: 'image/*',
        onDrop: (acceptedFiles) => {
          const uploadedFile = acceptedFiles[0];
          if (uploadedFile) {
            setFilePath(uploadedFile.name);
            setFile(uploadedFile);
            addFile(uploadedFile, 'image');
          }
        }
      });
    
      const handleFileChange = (event) => {
        const uploadedFile = event.target.files[0];
        if (uploadedFile) {
          setFilePath(uploadedFile.name);
          setFile(uploadedFile);
          addFile(uploadedFile, 'image');
        }
      };
    
      const handleUploadClick = () => {
        if (file) {
          // Perform any necessary validation or processing here
          navigate('/convertpreview/compresspdfpreview');  // Redirect to the preview page
        }
      };

    return (
        <>
        <div className={`dash-convert-mobile-container ${isDarkMode ? 'dark-mode' : 'light-mode'}`}>
        <Link to="/pages/dashboard" className="arrow-wrapper">
            <img className="arrow-icon" src={arrowback} />
            <div className="arrow-back-text">Back</div>
        </Link>

        <div className="frame-3045">
            <div className="merge-pdf">Compress to PDF</div>
            <div className="merge-files-into-a-single-file">
            Convert Powerpoint file to PDF
            </div>
        </div>

        {/*  */}
        <div {...getRootProps({ className: 'dropzone, upload-wrapper-box' })}>
            <div className="upload-inner-box">
                <input {...getInputProps()} />
                <img className="upload-icon-logo" src={docu2} alt="document" />
            </div>
            <div className="drag-and-drop">
                Drag and drop an image or select a file
            </div>
        </div>
        <div className="upload-url-and-bnt">
            <input type="text" className="upload-bottom-box" placeholder="Paste url..." readOnly value={filePath}/>
            <div className="url-btn">
                <input
                    type="file"
                    accept="pdf/*"
                    style={{ display: 'none' }}
                    onChange={handleFileChange}
                    id="fileInput"
                />
                <p className="url-btn-text" onClick={handleUploadClick}>Upload File</p>
            </div>
        </div>
        
        {/*  */}
        <div className="how-to-action-wrapper">
            <div className="how-to-merge-pdf">How to compress PDF</div>
            <div className="how-to-box">
                <div className="how-to-steps">
                    <div className="step-1">Step 1</div>
                    <div className="step-2">Step 2</div>
                    <div className="step-3">Step 3</div>
                </div>
                <div className="how-to-flow">
                    <div className="flow-box">
                        <div className="flow-box-1">
                            <div className="flow-circle-1 " />
                            <div className="flow-circle-2" />
                        </div>
                        <div className="line-4" />
                        <div className="flow-box-2">
                            <div className="flow-circle-3" />
                            <div className="flow-circle-4" />
                        </div>
                        <div className="line-5" />
                        <div className="flow-box-3">
                            <div className="flow-circle-5" />
                            <div className="flow-circle-6" />
                        </div>
                    </div>
                    <div className="frame-3048">
                        <div className="select-2-or-more-pdf-documents-to-upload-to-our-system">
                        Select a PowerPoint document to convert to PDF format
                        </div>
                        <div className="upload-the-pdf-files-from-a-pc-or-smart-phone">
                        Upload the PDF file from a Mac or PC, Android or iPhone
                        </div>
                        <div className="download-your-new-pdf">Download the converted PPT as PDF</div>
                    </div>
                </div>
            </div>
        </div>
        </div>
        </>
    )
}

export default CompressPdfComponent;