import React, {useContext} from "react";
import '../css/RecentFiles.css';
import recentavatar from '../images/recentavatar.svg';
import recentstar from '../images/recentstar.svg';
import DOMPurify from 'dompurify';
import 'react-quill/dist/quill.snow.css'; // Import the styles
import { ThemeContext } from "./context/ThemeContext";
import { MessageContext } from "./context/MessageContext";
import { UserContext } from "./context/ProfileContext";
import { Link } from "react-router-dom";

function RecentFiles() {
    const { isDarkMode } = useContext(ThemeContext);
  const { messages, approveMessage, declineMessage } = useContext(MessageContext);
  const {currentUser } = useContext(UserContext); // Access currentUser from context

  const Preview = ({ content }) => {
    const limitedContent = content.split(' ').slice(0, 10).join(' ') + (content.split(' ').length > 4 ? '...' : '');
    return (
      <div>
        <div className='preview-word' dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(limitedContent) }} />
      </div>
    );
  };

  // Function to determine the style based on the status
  const getStatusStyle = (status) => {
    switch (status) {
      case 'Approved':
        return { color: 'green' };
      case 'Declined':
        return { color: 'red' };
      case 'Pending':
        return { color: 'blue' };
      default:
        return {};
    }
  };
    return (
        <>
        <div className="recent-files">Recent Files</div>
        <div className="frame-65">
            <div className="frame-3033">
                <div className="check-box">
                    <input type="checkbox" className="check-boxt" />
                </div>
                <div className="username">Username</div>
            </div>
            <div className="description">Description</div>
        </div>
        {/* Message Rows */}
        <div className={`recent-files-main ${isDarkMode ? 'dark-mode' : 'light-mode'}`}>
              {/* Row */}
              {messages.length === 0 ? (
              <p>No recent available.</p>
              ) : (
              <ul style={{listStyle: 'none', width: '100%', marginLeft: '-40px'}}>
                {messages.map((message) => (
                <li key={message.id}>
                    <Link to={`/pages/message/${message.id}`} style={{textDecoration:"none"}}>
                        <div className="component-3-unique">
                            <div className="frame-61-unique">
                                <div className="check-box-unique">
                                    <input type="checkbox" className="rectangle-3036-unique"/>
                                </div>
                                <img className="star-4-unique" src={recentstar} />
                                <div className="frame-60-unique">
                                    <img className="avatar-8-unique" src={currentUser.profileImage} />
                                    <div className="group-1892-unique">
                                        <div className="fd-2481-41-b-unique">{message.id}</div>
                                        <div className="tom-hanks-unique">{currentUser.firstName} {currentUser.lastName}</div>
                                    </div>
                                </div>
                            </div>
                            <div className="frame-59-unique" />
                                <div className="statement-of-account-unique">
                                    <span>
                                        <span className="statement-of-account-span-unique">
                                        {message.subject}
                                        <br />
                                        </span>
                                        <span className="statement-of-account-span2-unique">
                                        <Preview content={message.body} />
                                        </span>
                                    </span>
                                </div>
                                
                            <div className="message-time-stamp">
                              <span className='document-status'>
                                <span className='document-status-text'>Status:</span>
                                <b style={getStatusStyle(message.status)}>{message.status}</b>
                              </span> 
                              <span className='message-date'>{message.date}</span>
                            </div>
                        </div>
                </Link>
              </li>
                ))}
                </ul>
                )}
            </div>

        </>
    )
}

export default RecentFiles;