import React, {useContext, useState} from 'react';
import { Helmet } from 'react-helmet';
import { FileContext } from '../assets/components/context/FileContext';
import DashboardHeader from '../assets/components/DashboardHeader';
import { ThemeContext } from '../assets/components/context/ThemeContext';
import JpgToPdfConvert from '../assets/components/JpgToPdfCovert';
import DashboardMenu from '../assets/components/DashboardMenu';
// import ConvertModal from '../assets/components/ConvertModalPopup';
import arrowback from '../assets/images/arrowback.svg';
import { Link, useNavigate } from 'react-router-dom';
import { jsPDF } from 'jspdf';

function CompressPdfPreview() {
  const { isDarkMode } = useContext(ThemeContext);
  const { imageFiles } = useContext(FileContext);
  const latestImageFile = imageFiles[imageFiles.length - 1];  // Get the latest uploaded file

  const [showModal, setShowModal] = useState(false);
  const navigate = useNavigate(); 
  const [pdfGenerated, setPdfGenerated] = useState(null); // To store generated PDF data
  // Function to handle convert button click
  const handleConvertClick = () => {
    setShowModal(true);  // Show the modal
  };

  // Function to close the modal
  const handleCloseModal = () => {
    setShowModal(false);  // Hide the modal
  };

const handleConvertToPDF = () => {
    if (latestImageFile) {
      // Create jsPDF instance
      const doc = new jsPDF();
      
      const reader = new FileReader();
      reader.onload = function (e) {
        const imgData = e.target.result;
        // Add image to PDF
        doc.addImage(imgData, 'JPEG', 10, 10, 180, 160);
        // Save the generated PDF
        const pdfOutput = doc.output('blob');
        setPdfGenerated(pdfOutput); // Store generated PDF in state

        // Automatically download the file
        doc.save('converted.pdf');
      };
      reader.readAsDataURL(latestImageFile);
    }
  };

  const handleAccept = () => {
    // Handle "Accept" action, e.g., converting to PDF
    setShowModal(false); // Hide the modal after accepting
    handleConvertToPDF(); // Call the conversion function
  };

  const handleDecline = () => {
    setShowModal(false); // Hide modal without converting
  };
  return (
    <>
    <Helmet>
      <title>Compress PDF Preview</title>
    </Helmet>
    <div className={`dashboard-main-container ${isDarkMode ? 'dark-mode' : 'light-mode'}`}>
      <DashboardHeader />
      <DashboardMenu />        
      <div className="dash-others">
        <div className="dash-convert-mobile-container">
        <Link to="/pages/dashboard" className="arrow-wrapper">
            <img className="arrow-icon" src={arrowback} />
            <div className="arrow-back-text">Back</div>
        </Link>

        <div className="frame-3045">
            <div className="merge-pdf">Compress PDF</div>
            <div className="merge-files-into-a-single-file">
            Compress PDF File
            </div>
        </div>
      
      {latestImageFile ? (
        <>
          <div className="preview-box">
            <img
              src={URL.createObjectURL(latestImageFile)}
              alt="JPG Preview"
              className="uploaded-preview"
            />
          </div>

          <div className="convert-button-wrapper" onClick={handleConvertClick}>
            <button className="convert-button">
              Split to PDF
            </button>
          </div>
        </>
      ) : (
        <p>No file uploaded yet. Please go back and upload a file.</p>
      )}

      {/* Popup Modal
      <ConvertModal
        showModal={showModal}
        handleClose={handleCloseModal}
        handleAccept={handleAccept}
      /> */}
      {showModal && (
        <div className="modal-overlay">
          <div className="modal-content">
            <p>Fidar will add i-Track code to your Converted File.</p>
            <div className="modal-buttons">
              <button className="accept-button" onClick={handleAccept}>
                Accept
              </button>
              <button className="decline-button" onClick={handleDecline}>
                Decline
              </button>
            </div>
          </div>
        </div>
      )}


      {/*  */}
      <div className="how-to-action-wrapper">
            <div className="how-to-merge-pdf">How to Compress PDF File</div>
            <div className="how-to-box">
                <div className="how-to-steps">
                    <div className="step-1">Step 1</div>
                    <div className="step-2">Step 2</div>
                    <div className="step-3">Step 3</div>
                </div>
                <div className="how-to-flow">
                    <div className="flow-box">
                        <div className="flow-box-1">
                            <div className="flow-circle-1 " />
                            <div className="flow-circle-2" />
                        </div>
                        <div className="line-4" />
                        <div className="flow-box-2">
                            <div className="flow-circle-3" />
                            <div className="flow-circle-4" />
                        </div>
                        <div className="line-5" />
                        <div className="flow-box-3">
                            <div className="flow-circle-5" />
                            <div className="flow-circle-6" />
                        </div>
                    </div>
                    <div className="frame-3048">
                        <div className="select-2-or-more-pdf-documents-to-upload-to-our-system">
                        Select one or more JPG images
                        </div>
                        <div className="upload-the-pdf-files-from-a-pc-or-smart-phone">
                        Upload to our servers for processing
                        </div>
                        <div className="download-your-new-pdf">Generate the PDF file and download with each image on a different page</div>
                    </div>
                </div>
            </div>
        </div>
    </div>
      </div>
    </div>
    </> 
  );
}

export default CompressPdfPreview;
