import React, { useState, useEffect } from "react";
import '../css/Dashboard.css';
import dashboard from '../images/dashboard.svg';
import indentdecrease from '../images/indentdecrease.svg';
import fidarlogo from '../images/fidarlogo.svg';
import inbox from '../images/inbox.svg';
import outbox from '../images/outbox.svg';
import draft from '../images/drafts.svg';
import grade from '../images/grade.svg';
import analytics from '../images/analytics.svg';
import folder from '../images/folder.svg';
import upload from '../images/upload.svg';
import folderopen from '../images/folderopen.svg';
import chat from '../images/chat.svg';
import folderdelete from '../images/folderdelete.svg';
import settings from '../images/settings.svg';
import help from '../images/help.svg';
import mydashicon from '../images/mydashicon.svg';
import { Link, NavLink } from "react-router-dom";
import { useContext } from 'react';
import { ThemeContext } from '../components/context/ThemeContext';

function DashboardMenu() {
     // State to control whether the menu is open or closed
     const [isMenuOpen, setIsMenuOpen] = useState(true);
    const { isDarkMode } = useContext(ThemeContext); // Access theme


     // Function to toggle the menu
     const toggleMenu = () => {
         setIsMenuOpen(!isMenuOpen);
     };

     // Check screen size on mount and set menu state accordingly
    useEffect(() => {
        const handleResize = () => {
            // Set the menu to be open on screen widths >= 1024px (laptops) and closed on smaller devices
            if (window.innerWidth >= 1024) {
                setIsMenuOpen(true);
            } else {
                setIsMenuOpen(false);
            }
        };

        // Initial check on mount
        handleResize();

        // Add a resize listener to update menu on window resize
        window.addEventListener('resize', handleResize);

        // Clean up the event listener on unmount
        return () => {
            window.removeEventListener('resize', handleResize);
        };
    }, []);

    // State to track the open/close status of each dropdown
    const [openDropMenu, setOpenDropMenu] = useState(null);

    // Function to toggle dropdown visibility
    const toggleMenuDropdown = (menu) => {
        setOpenDropMenu(openDropMenu === menu ? null : menu); // Close if clicked again
    };


    return (
        <>
        <div className={`mobile-logo-bar ${isDarkMode ? 'dark-mode' : 'light-mode'}`}>
            <div className="logo">
                    <img 
                        className="indent-decrease" 
                        src={indentdecrease} 
                        alt="Toggle Menu" 
                        onClick={toggleMenu} 
                        style={{ cursor: 'pointer' }}
                    />
            </div>
        </div>
        <div className="dash-col1">
            <div className={`dashboard-menu ${isMenuOpen ? 'open' : 'closed'} ${isDarkMode ? 'dark-mode' : 'light-mode'}`}>
                <div className="logo">
                    <img className="group-1 mobile-menu-logo" src={fidarlogo} />
                    <NavLink to="/" className="dash-fidar">FIDAR</NavLink>
                    <img 
                        className="indent-decrease mobile-menu-toggle2" 
                        src={indentdecrease} 
                        alt="Toggle Menu" 
                        onClick={toggleMenu} 
                        style={{ cursor: 'pointer' }}
                    />
                </div>
                <NavLink 
                    to="/pages/dashboard" 
                    className="list2" 
                    activeClassName="active-link"
                >
                    <i class="fa-solid fa-grip" style={{color: "#8b909a", marginLeft: "3px"}}></i>
                    {isMenuOpen && <div className="dashboard2">Dashboard</div>}
                </NavLink>
                <NavLink 
                    to="/pages/document" 
                    className="list2" 
                    activeClassName="active-link"
                >
                    <img className="move-to-inbox" src={inbox} />
                    {isMenuOpen && <div className="inbox">Document</div>}
                </NavLink>
                <NavLink 
                    to="/pages/archive" 
                    className="list2" 
                    activeClassName="active-link"
                >
                    <i className="fa-solid fa-box-archive" style={{color: "#8b909a", marginLeft: "3px"}}></i>
                    {isMenuOpen && <div className="starred">Archive</div>}
                </NavLink>
                <NavLink 
                    to="/pages/orcscan" 
                    className="list2" 
                    activeClassName="active-link"
                >
                    <i class="fa-solid fa-qrcode" style={{color: "#8b909a", marginLeft: "3px"}}></i>
                    {isMenuOpen && <div className="starred">Orc Scan</div>}
                </NavLink>
                <div className="list2" activeClassName="active-link">
                    <i class="fa-regular fa-note-sticky" style={{color: "#8b909a", marginLeft: "3px"}}></i>
                    {isMenuOpen && <div className="starred" onClick={() => toggleMenuDropdown('menu1')}>Inventory</div>}
                </div>
                <ul className="inventory-drop">
                    <li>
                    {openDropMenu === 'menu1' && (
                        <ul className="inventory-item-dropdown">
                            <li><NavLink to="/pages/incomingfiles" className="inventory-sub-link" activeClassName="active-link"><i class="fa-solid fa-satellite-dish"></i> Incoming Files</NavLink></li>
                            <li><NavLink to="/pages/outgoingfiles" className="inventory-sub-link" activeClassName="active-link"><i className="fa-regular fa-paper-plane"></i> Outgoing Files</NavLink></li>
                        </ul>
                    )}
                    </li>
                </ul>
                <NavLink 
                    to="/pages/trackrecords" 
                    className="list2" 
                    activeClassName="active-link"
                >
                    <img className="grade" src={analytics} />
                    {isMenuOpen && <div className="starred">i-Track</div>}
                </NavLink>
                <NavLink 
                    to="/pages/teamfolder" 
                    className="list2" 
                    activeClassName="active-link"
                >
                    <img className="grade" src={folder} />
                    {isMenuOpen && <div className="starred">Saved Password</div>}
                </NavLink>
                <NavLink 
                    to="/pages/trash" 
                    className="list2" 
                    activeClassName="active-link"
                >
                    <img className="grade" src={folderdelete} />
                    {isMenuOpen && <div className="starred">Trash</div>}
                </NavLink>
                <NavLink 
                    to="/pages/settings" 
                    className="list2"
                    activeClassName="active-link"
                    >
                    <img className="settings" src={settings} />
                    {isMenuOpen && <div className="inbox">Settings</div>}
                </NavLink>
                <div className="list2" activeClassName="active-link">
                    <i class="fa-regular fa-note-sticky" style={{color: "#8b909a", marginLeft: "3px"}}></i>
                    {isMenuOpen && <div className="starred" onClick={() => toggleMenuDropdown('menu2')}>Users</div>}
                </div>
                <ul className="inventory-drop">
                    <li>
                    {openDropMenu === 'menu2' && (
                        <ul className="inventory-item-dropdown">
                            <li><NavLink to="/pages/allusers" className="inventory-sub-link" activeClassName="active-link"><i class="fa-solid fa-satellite-dish"></i> All Users</NavLink></li>
                            <li><NavLink to="/pages/addnewuser" className="inventory-sub-link" activeClassName="active-link"><i className="fa-regular fa-paper-plane"></i> Add a New User</NavLink></li>
                        </ul>
                    )}
                    </li>
                </ul>
                <NavLink style={{marginBottom: "100px"}} 
                    to="/pages/help" 
                    className="list2" 
                    activeClassName="active-link"
                >
                    <img className="outbox" src={help} />
                    {isMenuOpen && <div className="inbox">Help</div>}
                </NavLink>
            </div>
        </div>
        </>
    );
}

export default DashboardMenu;
