import React from "react";
import { useContext } from 'react';
import { ThemeContext } from '../context/ThemeContext';

function Security() {
    const { isDarkMode } = useContext(ThemeContext); // Access theme

    return (
        <>
        <div className={`notification-title ${isDarkMode ? 'dark-mode' : 'light-mode'}`}>Update your password</div>
        <div className={`notification-sub-title ${isDarkMode ? 'dark-mode' : 'light-mode'}`}>You can update your password below. If you forgot your current password please
        contact support for assistance.</div>

        <form className={`${isDarkMode ? 'dark-mode' : 'light-mode'}`}>
            <input type="text" className="security-input" placeholder="Current passowrd" required/>
            <input type="text" className="security-input" placeholder="New passowrd" required/>
            <input type="text" className="security-input" placeholder="Confirm passowrd" required/>
            <button className="security-btn">
                <div className="save-changes">Save changes</div>
            </button>
        </form>

        </>
    )
}

export default Security;