import React from "react";
import HomeHeader from "../assets/components/HomeHeader";
import { Helmet } from "react-helmet";
import Footer from "../assets/components/Footer";
import '../assets/css/About.css';
import aboutimage from '../assets/images/aboutimage.svg';

function About() {
    return (
        <>
        <Helmet>
            <title>About Us - Fidar</title>
        </Helmet>
        <HomeHeader />
        <div className="about-container">
            <div className="about-top">
                <div className="about-fidar">About Fidar</div>
                <img className="about-top-image" src={aboutimage} />
            </div>

            <div className="about-content-container">
                <div className="about-content">
                    <div className="about-content-title">
                    Unleash the Power of Seamless Collaboration with Fidar
                    </div>
                    <div className="about-content-texts">
                    Sharing, Tracking, Chatting, Converting, Composing - All in One Platform
                    <br />
                    Are you tired of juggling multiple tools and struggling to keep your team
                    in sync? Look no further! Introducing Fidar, the ultimate solution for
                    modern professionals and teams. Fidar is a cutting-edge SaaS product
                    designed to revolutionize the way you manage files, communicate with team
                    members, convert documents, and compose content. With Fidar, you can
                    streamline your workflow, boost productivity, and foster seamless
                    collaboration, all within a single, intuitive platform.
                    </div>
                </div>
                <div className="about-content">
                    <div className="about-content-title">
                    Effortless File Sharing and Receiving
                    </div>
                    <div className="about-content-texts">
                    ay goodbye to the hassle of scattered files and confusing email threads.
                    With Fidar, file sharing becomes a breeze. Upload files from your local
                    storage or cloud services, organize them into folders, and securely share
                    them with colleagues or external partners. And the best part? You have
                    full control over who can view, edit, or comment on your files, ensuring
                    data privacy and confidentiality.
                    </div>
                </div>
                <div className="about-content">
                    <div className="about-content-title">
                    Track Progress in Real-time
                    </div>
                    <div className="about-content-texts">
                    No more guessing games or lost files. Fidar empowers you with advanced
                    file tracking capabilities. Stay informed about the progress of shared
                    files, know who accessed them, made changes, or left comments. With
                    real-time insights, you can identify bottlenecks, track revisions, and
                    ensure timely completion of tasks. Fidar's file tracking feature enhances
                    accountability, streamlines collaboration, and keeps your team on the same
                    page.
                    </div>
                </div>
                <div className="about-content">
                    <div className="about-content-title">
                    Seamless Communication and Collaboration
                    </div>
                    <div className="about-content-texts">
                    Effective teamwork relies on seamless communication. Fidar provides a
                    built-in chat functionality that keeps your conversations and files in one
                    place. Engage in one-on-one or group conversations, share files or links,
                    and collaborate instantly without switching between applications. Fidar's
                    integrated chat supports file attachments, ensuring all relevant
                    information remains consolidated within the conversation thread. Say
                    goodbye to scattered communication and hello to efficient collaboration.
                    </div>
                </div>
                <div className="about-content">
                    <div className="about-content-title">Effortless File Conversion</div>
                    <div className="about-content-texts">
                    Need to convert files into different formats? Fidar has got you covered.
                    Whether it's documents, images, audio files, or videos, Fidar's
                    comprehensive file conversion capabilities ensure compatibility and easy
                    access across devices and platforms. Say goodbye to third-party conversion
                    software or online tools. With Fidar, file conversion becomes effortless,
                    saving you time and effort.
                    </div>
                </div>
                <div className="about-content">
                    <div className="about-content-title">
                    Collaborative Document Composition
                    </div>
                    <div className="about-content-texts">
                    Creating documents has never been easier. Fidar empowers teams to compose
                    documents collaboratively. Start from scratch or import existing files,
                    invite team members to contribute, and work together in real-time. Fidar's
                    rich text editor with formatting options enables you to create
                    professional-looking documents effortlessly. Track changes, revert to
                    previous versions, and ensure a seamless document creation process with
                    Fidar.
                    <br />
                    Experience the power of seamless collaboration with Fidar. Sign up today
                    and unlock a world of efficient file management, streamlined
                    communication, and enhanced productivity. Leave behind the complexities of
                    scattered tools and embrace the simplicity and power of Fidar. Take
                    control of your workflows, empower your team, and achieve exceptional
                    results.
                    <br />
                    Ready to get started? Sign up for Fidar now and revolutionize the way you
                    work!
                    </div>
                </div>
            </div>
        </div>
        <Footer />
        </>
    )
}

export default About;