import React, { useContext } from "react";
import { Helmet } from "react-helmet";
import '../assets/css/Login.css';
import welcomeicon from '../assets/images/welcomeicon.svg';
import google from '../assets/images/google.svg';
import facebook from '../assets/images/facebook.svg';
import { Link } from "react-router-dom";
import { useNavigate } from "react-router-dom";
import { useState } from 'react';
import { UserContext } from "../assets/components/context/ProfileContext";
import TermsAndConditions from "../assets/components/TermsAndConditions";
import Modal from 'react-modal';

function Register() {
    const navigate = useNavigate();

    const { users, addUser } = useContext(UserContext);
    const [firstName, setFirstName] = useState('');
    const [lastName, setLastName] = useState('');
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState(''); // Password state
    // const [image, setImage] = useState(null);
    const [error, setError] = useState('');

    const handleSubmit = (e) => {
        e.preventDefault();

        // Check if the email already exists
        const emailExists = users.some((user) => user.email === email);

        if (emailExists) {
            setError('User with this email already exists!');
        } else {
            // Register new user
            const newUser = { firstName, lastName, email, password };
            addUser(newUser);
            setError('');
            // Optionally redirect to login or success page
            navigate("/pages/dashboard");
        }
    };

    // Set up the root element for accessibility
    Modal.setAppElement('#root');
    const [modalIsOpen, setModalIsOpen] = useState(false);

    const openModal = () => {
      setModalIsOpen(true);
    };
  
    const closeModal = () => {
      setModalIsOpen(false);
    };
    

    
    return (
        <>
        <Helmet>
            <title>Sign Up - Fidar</title>
        </Helmet>
        <div className="signup-page">
            <div className="sign-up-container">
                <div className="sign-up-contents">
                    <form className="frame-8" onSubmit={handleSubmit}>
                        <Link to="/"><img className="signup-back-to-home" src={welcomeicon} /></Link>
                        <div class="sign-up-title">Sign Up</div>
                        <div className="sign-up-with-title">
                            <div className="line">
                                <div className="rectangle-2926"></div>
                            </div>
                            <div className="group-2197">
                                <div className="sign-up-with-text">Sign up with</div>
                            </div>
                        </div>
                        <div className="frame-1">
                            <div className="signup-btn-google">
                                <div className="icon-colored-google">
                                    <img className="group-3269" src={google} />
                                </div>
                                <div className="signin-btn-google-text">Sign up with Google</div>
                            </div>
                            <div className="signup-btn-google">
                                <img className="icon-colored-facebook" src={facebook} />
                                <div className="signin-btn-google-text">Sign up with Facebook</div>
                            </div>
                        </div>
                        <div className="frame-2">
                            <div className="line2">
                                <div className="rectangle-29262"></div>
                            </div>
                            <div className="or">Or</div>
                            <div className="line2">
                                <div className="rectangle-29262"></div>
                            </div>
                        </div>
                        <div className="error-container">
                            {error && <p className="login-error">{error}</p>}
                        </div>
                        <div className="frame-6">
                            <div className="frame-3">
                                <div className="input">
                                    <div className="input-label">Name</div>
                                    <input
                                        type="text"
                                        className="name-input"
                                        placeholder="Name"
                                        value={firstName}
                                        onChange={(e) => setFirstName(e.target.value)}
                                        required
                                        />
                                </div>
                                <div className="input">
                                    <div className="input-label">Email</div>
                                    <input
                                        type="email"
                                        className="email-input"
                                        placeholder="Your email"
                                        autocomplete="email"
                                        value={email}
                                        onChange={(e) => setEmail(e.target.value)}
                                        required
                                    />
                                </div>
                            </div>
                            {/*  */}
                            <div className="frame-3">
                                <div className="input">
                                    <div className="input-label">Password</div>
                                    <input
                                        type="password"
                                        className="name-input"
                                        placeholder="Password"
                                        value={password}
                                        onChange={(e) => setPassword(e.target.value)}
                                        required
                                        />
                                </div>
                                <div className="input">
                                    <div className="input-label">Repeat Password</div>
                                    <input
                                        type="password"
                                        className="name-input"
                                        placeholder="Repeat Password"
                                        
                                    />
                                </div>
                            </div>
                            <div className="frame-3">
                                <div className="input">
                                    <div className="input-label">State</div>
                                    <input
                                        type="text"
                                        className="name-input"
                                        placeholder="Your state"
                                        
                                        />
                                </div>
                                <div className="input">
                                    <div className="input-label">City</div>
                                    <input
                                        type="text"
                                        className="email-input"
                                        placeholder="Your city"
                                        autocomplete="City"
                                    />
                                </div>
                            </div>
                                {/*  */}
                            <div className="frame-5">
                                <div class="frame-12">
                                    <input class="signup-check-box" type="checkbox" required/>
                                    <div class="i-agree-to-terms-conditions">
                                        <span>
                                            <span class="i-agree-to-terms-conditions-span">I agree to </span>
                                            <Link onClick={openModal} class="i-agree-to-terms-conditions-span2">
                                            terms &amp; conditions
                                            {/* <TermsAndConditions /> */}
                                            </Link>
                                        </span>
                                    </div>
                                </div>
                            </div>
                        </div>
                        <button type="submit" className="signup-submit">
                            <div className="button4">Sign Up</div>
                        </button>
                        <Link to="/pages/login" className="already-have-account">Sign In</Link>
                    </form>
                    
                </div>
            </div>
        </div>

        {/* Section for Modal Popup */}
        <Modal 
        isOpen={modalIsOpen} 
        onRequestClose={closeModal}
        contentLabel="Terms and Conditions"
        style={{
          content: {
            width: '50%',
            top: '50%',
            left: '50%',
            right: 'auto',
            bottom: 'auto',
            marginRight: '-50%',
            transform: 'translate(-50%, -50%)',
          },
        }}
      >
            <div><strong>Terms &amp; Conditions</strong></div>
            <div>
            <p>
                This is just a sample placeholder text for terms and condition.
            </p>
            </div>
            <button onClick={closeModal}>Close</button>
        </Modal>
        </>
    )
}

export default Register;