import React, {useState} from "react";
import '../css/Dashboard.css';
import search from '../images/search.svg';
import filter from '../images/filter.svg';
import notifications from '../images/notifications.svg';
import profile from '../images/profile.svg';
import { useContext } from 'react';
import { ThemeContext } from '../components/context/ThemeContext';
import '../css/ProfileDropdown.css';
import { Link } from "react-router-dom";
import SearchWithFilter from "./SearchWithFilter";
import '../css/SearchWithFilter.css';
import { UserContext } from "./context/ProfileContext";


function DashboardHeader() {
    const { isDarkMode } = useContext(ThemeContext); // Access theme
    const [isProfileOpen, setIsProfileOpen] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedFilter, setSelectedFilter] = useState('All');
    const [isSearchDropdownOpen, setIsSearchDropdownOpen] = useState(false);
    const {users, currentUser } = useContext(UserContext); // Access currentUser from context
  
    const toggleDropdown = () => {
        setIsProfileOpen(!isProfileOpen);
    }; 

    const handleSearch = (e) => {
      setSearchTerm(e.target.value);
    };

    const toggleSearchDropdown = () => {
      setIsSearchDropdownOpen(!isSearchDropdownOpen);
    };

    const selectFilter = (filter) => {
      setSelectedFilter(filter);
      setIsSearchDropdownOpen(false);
    };


    return (
        <>
        <div className={`op ${isDarkMode ? 'dark-mode' : 'light-mode'}`}>
            <input type="search" className="frame-9" value={searchTerm} onChange={handleSearch} placeholder="Search here..." />
            <img className="icons" src={search} />
            <img className="tune" src={filter} onClick={toggleSearchDropdown} /> 
            <span className="selected-filter">{selectedFilter}</span>
            {isSearchDropdownOpen && (
              <ul className={`dropdown-menu ${isDarkMode ? 'dark-mode' : 'light-mode'}`}>
                <li onClick={() => selectFilter('All')}>All</li>
                <li onClick={() => selectFilter('PDF')}>PDF</li>
                <li onClick={() => selectFilter('PNG')}>PNG</li>
                <li onClick={() => selectFilter('JPG')}>JPG</li>
                <li onClick={() => selectFilter('PowerPoints')}>PowerPoints</li>
                <li onClick={() => selectFilter('Excel')}>Excel</li>
              </ul>
            )}           
        </div>

        <div className="frame-3043">
            <img className="notifications" src={notifications} />
            <div className="hello-femi-welcome" onClick={toggleDropdown}>Hello {currentUser.firstName}</div>
            <div className="default-image-bg" onClick={toggleDropdown}>
              {currentUser.profileImage && (
                <img className="ellipse-1" onClick={toggleDropdown} src={currentUser.profileImage} />
              )}
            </div>
            
        </div>

        {isProfileOpen && (
        <div className={`profile-dropdown-menu ${isDarkMode ? 'dark-mode' : 'light-mode'}`}>
          <ul>
            <li><Link to="/pages/dashboard" className="profile-link"><i className="fa fa-gauge"></i> Dashboard</Link></li>
            <li><Link to="/pages/settings" className="profile-link"><i className="fa fa-user"></i> Profile</Link></li>
            <li><Link to="/pages/settings" className="profile-link"><i className="fa fa-bell"></i> Notification</Link></li>
            <li><Link to="/pages/help" className="profile-link" ><i className="fa-solid fa-circle-question"></i> Help</Link></li>
            <li><Link to="/pages/login" className="profile-link"><i className="fa-solid fa-right-from-bracket"></i> Logout</Link></li>
          </ul>
        </div>
      )}
        </>
    )
}

export default DashboardHeader;