import React from "react";
import { Helmet } from "react-helmet";
import '../assets/css/Dashboard.css';
import DashboardMenu from '../assets/components/DashboardMenu';
import DashboardHeader from "../assets/components/DashboardHeader";
import DashboardCard from "../assets/components/DashboardCard";
import Overview from "../assets/components/Overview";
import RecentFiles from "../assets/components/RecentFiles";
import DashRightSide from "../assets/components/DashRightSide";
import { useContext } from 'react';
import { ThemeContext } from '../assets/components/context/ThemeContext';
import { UserProvider } from "../assets/components/context/ProfileContext";

function Dashboard() {
    const { isDarkMode } = useContext(ThemeContext); // Access theme

    return (
        <>
        <Helmet>
            <title>Dashboard - Fidar</title>
        </Helmet>
        <UserProvider>
        <div className={`dashboard-main-container ${isDarkMode ? 'dark-mode' : 'light-mode'}`}>
            <div className="dash-col1">
                <DashboardMenu />
            </div>
            <div className="dash-header-freeze">
                <DashboardHeader />
            </div>
            <div className="dash-col2">
                <div className="dashboard-main">
                    <DashboardCard />
                    <Overview />
                    <RecentFiles />
                </div>
            </div>
            <div className="dash-col3">
                <DashRightSide />
            </div>
        </div>
        </UserProvider>
        </>
    )
}

export default Dashboard;